BATAS_LULUS = 75

def sapa(nama):
    print("Halo,", nama + "!")

def hitung_total(nilai1, nilai2, nilai3):
    total = nilai1 + nilai2 + nilai3
    return total

def hitung_rata_rata(total, jumlah):
    return total / jumlah

def tentukan_status(rata_rata):
    if rata_rata >= BATAS_LULUS:
        return "Lulus"
    return "Belum lulus"

def tampilkan_hasil(nama, total, rata_rata):
    print("Total nilai:", total)
    print("Rata-rata:", rata_rata)
    print("Status:", tentukan_status(rata_rata))

sapa("Andi")
nilai_total = hitung_total(80, 90, 100)
nilai_rata = hitung_rata_rata(nilai_total, 3)
tampilkan_hasil("Andi", nilai_total, nilai_rata)
